10	<body>
11	<h1>预览索引</h1>
12	<p class="field-value">筛选值：newsletter</p>
13	<p>分组命中：4；排除：1；最终预览：3</p>
14	<div class="contact-search">
15	<label for="contact-search">搜索姓名或邮箱：</label>
16	<input type="text" id="contact-search">
17	<span id="search-count">当前显示 3 条，共 3 条</span>
18	</div>
19	<table>
20	<thead><tr><th>姓名</th><th>邮箱</th><th>预览</th></tr></thead>
21	<tbody>
22	<tr class="retained-row"><td class="field-value">甲</td><td class="field-value">shared@example.invalid</td><td><a href="preview-0001.txt">预览</a></td></tr>
23	<tr class="retained-row"><td class="field-value">乙</td><td class="field-value">shared@example.invalid</td><td><a href="preview-0002.txt">预览</a></td></tr>
24	<tr class="retained-row"><td class="field-value">丙</td><td class="field-value">b@example.invalid</td><td><a href="preview-0003.txt">预览</a></td></tr>
25	<tr id="search-empty-row" hidden><td colspan="3">没有符合搜索条件的联系人</td></tr>
26	</tbody>
27	</table>
28	<h2>已排除的联系人</h2>
29	<table>
30	<thead><tr><th>姓名</th><th>邮箱</th></tr></thead>
31	<tbody>
32	<tr><td class="field-value">丁</td><td class="field-value">cut@example.invalid</td></tr>
33	</tbody>
34	</table>
35	<script>
36	(function () {
37	"use strict";
38	var box = document.getElementById("contact-search");
39	var emptyRow = document.getElementById("search-empty-row");
40	var count = document.getElementById("search-count");
41	var rows = Array.prototype.slice.call(
42	document.getElementsByClassName("retained-row"));
43	var fields = [["甲", "shared@example.invalid"], ["乙", "shared@example.invalid"], ["丙", "b@example.invalid"]];
44	function applyFilter() {
45	  var query = box.value;
46	  var index;
47	  var show;
48	  var visible = 0;
49	  for (index = 0; index < rows.length; index += 1) {
50	    show = query === '' ||
51	      fields[index][0].indexOf(query) !== -1 ||
52	      fields[index][1].indexOf(query) !== -1;
53	    rows[index].hidden = !show;
54	    if (show) {
55	      visible += 1;
56	    }
57	  }
58	  if (emptyRow !== null) {
59	    emptyRow.hidden = query === '' || visible !== 0;
60	  }
61	  count.textContent = "当前显示 " + visible + " 条，共 " + rows.length + " 条";
62	}
63	box.addEventListener("input", applyFilter);
64	applyFilter();
65	}());
66	</script>
67	</body>
68	</html>
