cat > /tmp/acc/simulate.js <<'EOF'
// 用最小 DOM 桩真实执行页面内联脚本，逐个查询核对计数与可见性。
const fs = require("fs");
const raw = fs.readFileSync(process.argv[2], "utf8");
const script = raw.match(/<script>([\s\S]*?)<\/script>/)[1];

const retainedCount = (raw.match(/<tr class="retained-row">/g) || []).length;
const rows = Array.from({length: retainedCount}, () => ({hidden: false}));
const emptyRow = raw.includes('id="search-empty-row"') ? {hidden: true} : null;
const count = {textContent: ""};
const box = {value: "", listeners: {},
  addEventListener(ev, fn) { this.listeners[ev] = fn; }};
const byId = {
  "contact-search": box,
  "search-empty-row": emptyRow,
  "search-count": count,
};
const document = {
  getElementById: (id) => byId[id],
  getElementsByClassName: (cls) => cls === "retained-row" ? rows : [],
};
eval(script);

for (const query of process.argv.slice(3)) {
  box.value = query;
  box.listeners.input();
  console.log(JSON.stringify({
    query,
    count: count.textContent,
    visible: rows.filter(r => !r.hidden).length,
    hintHidden: emptyRow ? emptyRow.hidden : null,
  }));
}
EOF
node /tmp/acc/simulate.js /tmp/acc/previews/index.html "" shared zzz 丙 Shared

